// Distinct qualified PG Ledger4 consumer. Parsed evidence is never a grant;
// only complete held snapshot + exact imported SQL + fresh destination can seal.
use crate::storage::restoration::composite as pg_composite;
fn pg_composite_capture_nonnull<'de,D:serde::Deserializer<'de>>(d:D)->Result<Option<pg_composite::CompositeCaptureEvidence>,D::Error>{use serde::Deserialize;pg_composite::CompositeCaptureEvidence::deserialize(d).map(Some)}
struct PgValidatedCompositeCapture {manifest_sha256:String,evidence_sha256:String}
fn pg_composite_capsules(snapshot:&InspectedPgSnapshot)->std::collections::BTreeSet<String>{snapshot.manifest.files.0.iter().filter_map(|(p,e)|if matches!(e,PgSnapshotEntry::Directory{..}){p.strip_prefix(".attachment-upload-admission/").filter(|p|!p.contains('/')).map(str::to_owned)}else{None}).collect()}
fn pg_composite_raw(snapshot:&InspectedPgSnapshot,path:&str,length:u64,sha:&str)->anyhow::Result<Vec<u8>>{
 ensure!(length<=8*1024*1024,"Composite PG typed record exceeds raw bound");let role=snapshot.held.roles.get(&format!("files/{path}")).context("Composite PG held record absent")?;ensure!(role.bytes.size_bytes==length&&role.bytes.sha256==sha&&physical_stamp(&role.held)?==role.stamp,"Composite PG held record changed");let mut raw=vec![0;length as usize];role.held.read_exact_at(&mut raw,0)?;ensure!(digest(&raw)==sha&&physical_stamp(&role.held)?==role.stamp,"Composite PG record changed during read");Ok(raw)
}
fn pg_composite_directory(snapshot:&InspectedPgSnapshot,path:Option<String>,id:&admission::Identity)->anyhow::Result<()>{
 let current=match path{Some(p)=>match snapshot.manifest.files.0.get(&p){Some(PgSnapshotEntry::Directory{device,inode})=>(*device,*inode),_=>bail!("Composite PG directory role absent")},None=>(snapshot.manifest.source_root.device,snapshot.manifest.source_root.inode)};ensure!(current==(id.device,id.inode),"Composite PG exact directory custody differs");Ok(())
}
fn pg_composite_pending(snapshot:&InspectedPgSnapshot,scope:&admission::AdmissionOwnerScope)->anyhow::Result<()> {
 use admission::{DirectoryRole,FileRole};let mut raws=BTreeMap::new();
 let producer:crate::storage::attachment_upload::admission::Producer=serde_json::from_value(serde_json::from_str::<serde_json::Value>(&scope.original_claim_json)?["producer"].clone())?;ensure!(matches!(producer,crate::storage::attachment_upload::admission::Producer::Direct{..}),"Composite PG pending Replay requires separate qualified class");
 for b in &scope.files{let path=b.role.relative(&scope.attempt_id)?;let Some(PgSnapshotEntry::File{device,inode,length,sha256,..})=snapshot.manifest.files.0.get(&path)else{bail!("Composite PG pending captured file absent")};ensure!(b.captured==(admission::Identity{device:*device,inode:*inode})&&b.length==*length&&b.sha256==*sha256,"Composite PG pending original custody/bytes differ");if matches!(&b.role,FileRole::DirectStage{name} if name=="payload.part"){let f=&snapshot.held.roles.get(&format!("files/{path}")).context("Composite PG pending held body absent")?.held;crate::storage::attachment_upload::admission::verify_captured_direct_payload(f,b.length,&b.sha256,scope.maximum_bytes)?;raws.insert(b.role.clone(),Vec::new());}else{raws.insert(b.role.clone(),pg_composite_raw(snapshot,&path,b.length,&b.sha256)?);}}
 for b in &scope.directories{let p=b.role.relative(&scope.attempt_id)?;ensure!(p.is_some()||b.role==DirectoryRole::DataRoot,"Composite PG pending root role differs");pg_composite_directory(snapshot,p,&b.captured)?;}
 crate::storage::attachment_upload::admission::validate_captured_partial_direct(scope,&raws)?;snapshot.held.fence()?;Ok(())
}
async fn pg_validate_composite_capture(snapshot:&InspectedPgSnapshot,tx:&mut sqlx::Transaction<'_,sqlx::Any>)->anyhow::Result<Option<PgValidatedCompositeCapture>>{
 let Some(e)=&snapshot.manifest.composite_admission_capture else{return Ok(None)};e.validate_shape()?;snapshot.held.fence()?;ensure!(snapshot.profile.has_erasure(),"Composite PG requires exact53/7 profile");pg_prior_completed_roles(snapshot)?;
 e.check_complete_reservation_census_in(&mut **tx,&pg_composite_capsules(snapshot)).await?;
 let copied_root=Root::open(&snapshot.held.root.absolute.join("files"))?;let designation=crate::storage::data_root_designation::Designation::capture_held(&copied_root.absolute,copied_root.fd())?;
 let paths=snapshot.manifest.files.0.iter().filter_map(|(p,e)|matches!(e,PgSnapshotEntry::File{..}).then_some(p.clone())).collect::<std::collections::BTreeSet<_>>();
 let files=snapshot.manifest.files.0.iter().filter_map(|(p,e)|match e{PgSnapshotEntry::File{device,inode,length,sha256,..}=>Some((p.clone(),(*device,*inode,*length,sha256.clone()))),_=>None}).collect::<BTreeMap<_,_>>();
 let mut stages=e.prior.roles.scopes.iter().map(|s|s.original.reservation.operation_id.clone()).collect::<std::collections::BTreeSet<_>>();
 for scope in &e.native{
  let attempt=&scope.reservation.operation_id;let mut raws=BTreeMap::new();
  for b in &scope.directories{pg_composite_directory(snapshot,b.role.relative(attempt)?,e.source_directory(scope,&b.role)?)?;}
  for b in &scope.files{let path=b.role.relative(attempt)?;let Some(PgSnapshotEntry::File{device,inode,links,length,sha256})=snapshot.manifest.files.0.get(&path)else{bail!("Composite PG native record absent")};let captured=e.source_file(scope,&b.role)?;ensure!((*device,*inode)==(captured.device,captured.inode)&&*links==1&&*length==b.length&&sha256==&b.sha256,"Composite PG native record original custody differs");raws.insert(b.role.clone(),pg_composite_raw(snapshot,&path,b.length,&b.sha256)?);}
  let record=crate::storage::attachment_upload::admission::validate_composite_native_records(scope,&raws)?;record.validate_snapshot_row_and_paths_in(&mut **tx,&paths).await?;
  let mut owned=scope.files.iter().map(|b|b.role.relative(attempt)).collect::<std::io::Result<std::collections::BTreeSet<_>>>()?;
  match &scope.class{
   pg_composite::NativeClass::Reserved{original_scope:Some(p)}=>{pg_composite_pending(snapshot,&e.pending_scope(scope)?.context("Composite PG pending captured scope absent")?)?;for query in ["SELECT COUNT(*) FROM attachment_upload_receipts WHERE attempt_id=$1","SELECT COUNT(*) FROM attachment_version_records WHERE upload_attempt_id=$1"]{let count:i64=sqlx::query_scalar(query).bind(attempt).fetch_one(&mut **tx).await?;ensure!(count==0,"Composite PG pending original already has winner");}for b in &p.files{owned.insert(b.role.relative(attempt)?);}},
   pg_composite::NativeClass::Reserved{original_scope:None}=>bail!("Composite PG pre-stage pending has no supported cold proof"),
   pg_composite::NativeClass::CommittedDirect{..}=>{let role=pg_composite::FileRole::CapsuleRecord{name:pg_composite::CapsuleRecord::StageOrigin};if e.prior_scope(scope).is_some(){pg_composite_prior_committed(snapshot,&mut **tx,scope,&raws,&files).await?;}else{record.check_captured_committed_in(&mut **tx,raws.get(&role).context("Composite PG committed origin absent")?,&files).await?;}owned.insert(format!(".attachment-upload-journal/{attempt}/payload.part"));},
   pg_composite::NativeClass::DisposedDirect{..}|pg_composite::NativeClass::DisposedReplay{..}=>{for(path,(device,inode,_,_))in &files{let held=&snapshot.held.roles.get(&format!("files/{path}")).context("Composite PG complete held file absent")?.held;record.check_captured_disposed_file(path,*device,*inode,held,designation.as_ref())?;}crate::storage::attachment_upload::admission::committed_erasure::accounting::composite::check_disposed_snapshot_references_in(&copied_root.absolute,&mut **tx,scope.reservation.disposition_json.as_deref().context("Composite PG original raw disposition absent")?,matches!(scope.class,pg_composite::NativeClass::DisposedReplay{..})).await?;},
  }
  let mut prefixes=vec![format!(".attachment-upload-admission/{attempt}/")];if scope.directories.iter().any(|b|b.role==pg_composite::DirectoryRole::DirectStageDirectory){stages.insert(attempt.clone());prefixes.push(format!(".attachment-upload-journal/{attempt}/"));}
  let observed=paths.iter().filter(|p|prefixes.iter().any(|prefix|p.starts_with(prefix))).cloned().collect::<std::collections::BTreeSet<_>>();ensure!(observed==owned&&!snapshot.manifest.files.0.iter().any(|(p,e)|matches!(e,PgSnapshotEntry::Directory{..})&&prefixes.iter().any(|prefix|p.starts_with(prefix))),"Composite PG full native capsule/stage topology differs");
 }
 let observed_stages=snapshot.manifest.files.0.iter().filter_map(|(p,e)|if matches!(e,PgSnapshotEntry::Directory{..}){p.strip_prefix(".attachment-upload-journal/").filter(|p|!p.contains('/')).map(str::to_owned)}else{None}).collect::<std::collections::BTreeSet<_>>();ensure!(stages==observed_stages,"Composite PG complete Direct stage census differs");if let Some(d)=&designation{d.fence()?;}e.check_complete_reservation_census_in(&mut **tx,&pg_composite_capsules(snapshot)).await?;snapshot.held.fence()?;Ok(Some(PgValidatedCompositeCapture{manifest_sha256:digest(&snapshot.held.manifest),evidence_sha256:digest(&serde_json::to_vec(e)?)}))
}
fn pg_certified_composite_roles(snapshot:&InspectedPgSnapshot,d:&OwnedPgBackup,proof:Option<&PgValidatedCompositeCapture>,completed:Option<&completed::CompletedOwnerEnvelope>)->anyhow::Result<Option<pg_composite::CompositeOwnerEnvelope>>{
 let Some(e)=&snapshot.manifest.composite_admission_capture else{ensure!(proof.is_none(),"Unexpected composite PG proof");return Ok(None)};let proof=proof.context("Composite PG private exact imported proof absent")?;ensure!(proof.manifest_sha256==digest(&snapshot.held.manifest)&&proof.evidence_sha256==digest(&serde_json::to_vec(e)?),"Composite PG proof source differs");snapshot.held.fence()?;d.fence()?;let completed=completed.context("Composite PG completed component absent")?.clone();ensure!(completed.version==2,"Composite PG fresh completed owner must use per-scope source basis");
 let pending=e.native.iter().map(|s|e.pending_scope(s)).collect::<Result<Vec<_>,_>>()?.into_iter().flatten().collect::<Vec<_>>();let pending=if pending.is_empty(){None}else{pg_certified_admission_scope_set(snapshot,d,None,admission::AdmissionOwnerEnvelope{version:2,scopes:pending})?};
 let mut native=Vec::new();for original in &e.native{let attempt=&original.reservation.operation_id;let mut directories=Vec::new();let mut files=Vec::new();for b in &original.directories{let adopted=if let Some(path)=b.role.relative(attempt)?{let(f,stamp)=d.directories.get(&path).context("Composite PG fresh directory absent")?;ensure!(physical_stamp(f)?==*stamp&&f.metadata()?.mode()&0o777==0o700,"Composite PG fresh directory differs");admission::Identity{device:stamp.device,inode:stamp.inode}}else{admission::Identity{device:d.root_identity.0,inode:d.root_identity.1}};directories.push(pg_composite::OwnedDirectory{role:b.role.clone(),adopted});}for b in &original.files{let path=b.role.relative(attempt)?;let source=snapshot.held.roles.get(&format!("files/{path}")).context("Composite PG source file absent")?;let target=d.roles.get(&path).context("Composite PG fresh file absent")?;ensure!(target.bytes==source.bytes&&physical_stamp(&target.held)?==target.stamp&&target.stamp.links==1&&target.stamp.mode&0o777==0o600,"Composite PG fresh file differs");files.push(pg_composite::OwnedFile{role:b.role.clone(),adopted:admission::Identity{device:target.stamp.device,inode:target.stamp.inode}});}native.push(pg_composite::NativeOwnerScope{original:original.clone(),source_basis:e.source_basis(original),directories,files,pending:pending.as_ref().and_then(|p|p.scopes.iter().find(|s|s.attempt_id==*attempt)).cloned()});}
 let roles=pg_composite::CompositeOwnerEnvelope{version:e.version,completed,native};roles.validate(&admission::Identity{device:d.root_identity.0,inode:d.root_identity.1})?;snapshot.held.fence()?;d.fence()?;Ok(Some(roles))
}
#[cfg(test)]
mod pg_composite_contract_tests {
 use super::*;
 #[derive(serde::Deserialize)]#[serde(deny_unknown_fields)]
 struct Optional{#[serde(default,deserialize_with="pg_composite_capture_nonnull")] composite_admission_capture:Option<pg_composite::CompositeCaptureEvidence>}
 #[test]fn strict_composite_optional_transport(){
  assert!(serde_json::from_str::<Optional>("{}").unwrap().composite_admission_capture.is_none());
  for raw in [r#"{"composite_admission_capture":null}"#,r#"{"composite_admission_capture":false}"#,r#"{"composite_admission_capture":{}}"#,r#"{"composite_admission_capture":{},"composite_admission_capture":{}}"#,r#"{"composite_admission_capture":{"version":1,"foreign":true}}"#]{assert!(serde_json::from_str::<Optional>(raw).is_err());}
 }
}

// Purpose-bound old committed upload observation. No copied WriterLease or
// synthetic original identity: every current inode must match the exact sealed
// predecessor upload binding and immutable original install-proof digest.
async fn pg_composite_prior_committed(snapshot:&InspectedPgSnapshot,conn:&mut sqlx::AnyConnection,scope:&pg_composite::NativeScope,raws:&BTreeMap<pg_composite::FileRole,Vec<u8>>,files:&BTreeMap<String,(u64,u64,u64,String)>)->anyhow::Result<()>{
 let e=snapshot.manifest.composite_admission_capture.as_ref().context("Repeated committed evidence absent")?;ensure!(e.version==2&&e.prior_scope(scope).is_some(),"Repeated committed scope not authenticated prior");pg_prior_completed_roles(snapshot)?;
 let pg_composite::NativeClass::CommittedDirect{receipt_json}=&scope.class else{bail!("Repeated committed typed class differs")};let receipt:crate::storage::attachment_upload::Receipt=serde_json::from_str(receipt_json)?;
 let origin:serde_json::Value=serde_json::from_slice(raws.get(&pg_composite::FileRole::CapsuleRecord{name:pg_composite::CapsuleRecord::StageOrigin}).context("Repeated committed original stage origin absent")?)?;let device=origin["payload"]["device"].as_u64().context("Repeated committed original payload device absent")?;let inode=origin["payload"]["inode"].as_u64().context("Repeated committed original payload inode absent")?;
 let proof=scope.files.iter().find(|b|b.role==pg_composite::FileRole::DirectStageRecord{name:pg_composite::StageRecord::InstallProof}).context("Repeated committed original install proof role absent")?;
 let raw=snapshot.history.raw_generations.get(&e.prior.generation_id).context("Repeated committed sealed generation absent")?;let old:HistoryEnvelope=serde_json::from_slice(raw)?;let upload=old.runtime.scopes.iter().find(|s|s.namespace==".attachment-upload-journal"&&s.op_id==scope.reservation.operation_id&&s.evidence_sha256==proof.sha256).context("Repeated committed original upload proof scope absent")?;
 for path in [&receipt.intent.storage_path,&format!(".attachment-upload-journal/{}/payload.part",receipt.intent.attempt_id)]{let b=upload.bindings.iter().find(|b|&b.relative==path).context("Repeated committed exact historical path absent")?;let(current_device,current_inode,length,sha)=files.get(path).context("Repeated committed captured source file absent")?;ensure!((b.original_device,b.original_inode)==(device,inode)&&(b.adopted_device,b.adopted_inode)==(*current_device,*current_inode)&&b.length==*length&&b.sha256==*sha&&*length==receipt.intent.byte_length as u64&&*sha==receipt.intent.binary_sha256,"Repeated committed current identity/original proof/bytes differ");}
 crate::storage::attachment_versions::validate_composite_preserved_singleton_in(conn,&receipt).await.map_err(anyhow::Error::msg)?;snapshot.held.fence()?;Ok(())
}
